cedar:
// SPEC §8 rule 2: the sandbox never touches real channels. A forbid always beats a permit.
@id("sandbox_never_real_channels")
forbid(
  principal,
  action in [
    Action::"place_checkin_call",
    Action::"assign_volunteer",
    Action::"broadcast_to_volunteers",
    Action::"notify_family"
  ],
  resource
)
when { context.session.mode == "sandbox" && context.session.channel == "real" };

// SPEC §8 rule 1: real calls go only to allowlisted, consenting residents, within attempt and
// quiet-hour limits (8 AM to 9 PM local unless the alert is Extreme), and only in live mode.
// Quiet hours are waived for one case only: an incident flagged `operator_test` calling the
// operator's own test number (every other condition still applies). Decided 2026-09-12, Phase 4.
@id("real_call_guarded")
permit(principal, action == Action::"place_checkin_call", resource)
when {
  context.session.mode == "live" &&
  context.session.callee_allowlisted == true &&
  context.session.callee_consented == true &&
  context.session.attempts_last_hour < 3 &&
  ((context.session.local_hour >= 8 && context.session.local_hour < 21) ||
   context.session.alert_severity == "Extreme" ||
   context.session.operator_test_call == true)
};

// SPEC §8 rule 3: resident details go only to the captain or the volunteer assigned to that
// resident. The brief travels only inside assign_volunteer (to that one volunteer), and only when
// that volunteer is available and within range. High-risk assignments additionally pause for
// captain approval (Strands interrupt, Phase 2).
@id("assign_available_nearby_volunteer")
permit(principal, action == Action::"assign_volunteer", resource)
when {
  context.session.volunteer_available == true &&
  context.session.volunteer_distance_km < 3
};

// Group broadcasts never contain resident details.
@id("broadcast_without_resident_details")
permit(principal, action == Action::"broadcast_to_volunteers", resource)
when { context.input.include_resident_details == false };

// SPEC §8 rule 4: family contact requires the resident's consent.
@id("family_contact_needs_consent")
permit(principal, action == Action::"notify_family", resource)
when { context.session.family_consent == true };

// SPEC §8 rule 5: emergency calls are recorded by humans only. Doorstep never contacts emergency
// services itself; it tells the resident to call 911 and pages a human. The agent principal
// (role "agent") never matches this permit, so its attempts are denied and audited.
@id("emergency_calls_recorded_by_captain_only")
permit(principal, action == Action::"record_emergency_call", resource)
when { context.session.role == "captain" };

// SPEC §8 rule 6: read-only tools are always allowed, plus the side-effect-free helpers the
// spec lists as "always permitted" (timers, resident tips, escalation, closing a case).
@id("read_only_always")
permit(
  principal,
  action in [
    Action::"get_org_profile",
    Action::"get_roster",
    Action::"score_residents",
    Action::"get_resident_memory",
    Action::"find_relief_centres",
    Action::"find_nearest_volunteers",
    Action::"schedule_recheck",
    Action::"send_resident_tip",
    Action::"escalate_to_captain",
    Action::"close_case"
  ],
  resource
);

// Simulated check-ins only exist in drills and the sandbox (SPEC §7).
@id("simulated_checkins_outside_live")
permit(principal, action == Action::"start_simulated_checkin", resource)
when { ["drill", "sandbox"].contains(context.session.mode) };
